import { sendBookingRequest } from "@/lib/telegram"
import { sendBookingsList } from "@/lib/telegram-client"

async function test1() {
  try {
    const result = await sendBookingsList('all')

    if (result) {
      console.log("Booking list successfully sent")
    } else {
      console.log("Failed to send booking list")
    }
  } catch (error) {
    console.error("Error sending bookings list:", error)
    console.log("An error occurred while sending booking list")
  }
}

